        {id:"file-write-w",type:"write",prompt:'Define save_note(filename, text) to save text in the given file. Save "MEOWDE" to note.txt, then read the file and print its contents.',starter:"# Define save_note(filename, text), then verify the file\n",expected:"MEOWDE",testcase:"Expected output: MEOWDE",hint:'Inside with open(filename, "w"), call file.write(text).',explain:"Turning file writing into a function makes both filename and content reusable.",model:'def save_note(filename, text):\n    with open(filename, "w") as file:\n        file.write(text)\nsave_note("note.txt", "MEOWDE")\nwith open("note.txt", "r") as file:\n    print(file.read())',grading:{tests:[{append:'save_note("other.txt", "PYTHON")\nprint(open("other.txt", "r").read())',expected:"PYTHON",labelKo:"다른 파일과 내용",labelEn:"another file and text"}]},diagnostic:{ko:{cause:"파일 이름과 text를 함수 인자로 사용해 저장하지 않았어요.",reason:"note.txt의 MEOWDE는 맞지만 다른 파일 이름과 내용으로 바꾸면 같은 저장 규칙이 동작하지 않아요.",action:'with open(filename, "w")에서 file.write(text)를 호출하세요.'},en:{cause:"The function is not saving the filename and text it receives.",reason:"The note.txt example works, but another filename and text do not follow the same save rule.",action:'Use with open(filename, "w") and call file.write(text).'}}}
