        {id:"file-lines-b",type:"bughunt",prompt:"Which line increments count for every line even though empty lines should not be counted?",lines:['for line in file:','    if line.strip():','        count += 1','    count += 1'],buggy:3,fixed:'        count += 1',hint:"Increment only inside the condition that checks for content.",explain:"Keep count += 1 only inside if line.strip(): so empty lines are ignored."},
        {id:"file-lines-w",type:"write",prompt:"Define count_nonempty(filename) to return only the number of lines containing text. Create pets.txt with cat, an empty line, and dog, then print the result.",starter:"# Create pets.txt and define count_nonempty(filename)\n",expected:"2",testcase:"Expected output: 2",hint:"Loop with for line in file and increment count only when line.strip() is truthy.",explain:"Combining file iteration with string cleanup lets you process line-based data safely.",model:'with open("pets.txt", "w") as file:\n    file.write("cat\\n\\ndog\\n")\ndef count_nonempty(filename):\n    count = 0\n    with open(filename, "r") as file:\n        for line in file:\n            if line.strip():\n                count += 1\n    return count\nprint(count_nonempty("pets.txt"))',grading:{tests:[{append:'with open("three.txt", "w") as file:\n    file.write("a\\nb\\nc\\n")\nprint(count_nonempty("three.txt"))',expected:"3",labelKo:"다른 줄 구성",labelEn:"another line set"}]},diagnostic:{ko:{cause:"내용이 있는 줄만 세는 규칙이 일반화되지 않았어요.",reason:"예시 파일에서는 2가 맞지만 다른 줄 구성에서 실제 비어 있지 않은 줄의 개수를 세지 못했어요.",action:"for line in file 안에서 if line.strip():일 때만 count += 1 하세요."},en:{cause:"The non-empty-line rule does not generalize.",reason:"The example gives 2, but another file does not count only the lines that contain text.",action:"Inside for line in file, increment count only when line.strip() is truthy."}}}
